import Link from 'next/link';

export default function SpecialtiesLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <div style={{ border: '2px dashed #3498db', padding: '20px', borderRadius: '8px' }}>
      <h3 style={{ marginTop: 0, color: '#2c3e50' }}>Розділ спеціальностей коледжу</h3>
      
      <div style={{ marginBottom: '15px', display: 'flex', gap: '20px' }}>
        <Link href="/specialties" style={{ color: '#2980b9', fontWeight: 'bold' }}>Усі спеціальності</Link>
        <Link href="/specialties/programming" style={{ color: '#2980b9', fontWeight: 'bold' }}>Програмування</Link>
        <Link href="/specialties/design" style={{ color: '#2980b9', fontWeight: 'bold' }}>Дизайн</Link>
      </div>

      <hr style={{ border: '0', borderTop: '1px solid #ddd', marginBottom: '15px' }} />

      <div>{children}</div>
    </div>
  );
}